"use client";

import { MoonIcon, SunIcon } from "lucide-react";
import { motion } from "motion/react";
import type { ComponentProps } from "react";
import { Button } from "@/components/ui/button";
import type { ThemeState } from "@/hooks/use-theme-toggle";
import { useThemeToggle } from "@/hooks/use-theme-toggle";
import { cn } from "@/lib/utils";
import {
	IconSwap,
	IconSwapItem,
} from "@/registry/components/icon-swap/icon-swap";

export type ThemeStateIconProps = {
	state: ThemeState | null;
	/** Custom icon for the light theme. */
	lightIcon?: React.ReactNode;
	/** Custom icon for the dark theme. */
	darkIcon?: React.ReactNode;
};

export function ThemeStateIcon({
	state,
	lightIcon,
	darkIcon,
}: ThemeStateIconProps) {
	if (!state) {
		return <span className="block size-4" aria-hidden />;
	}

	return (
		<IconSwap>
			<IconSwapItem
				key={state}
				as={motion.span}
				aria-hidden
				data-icon="inline-start"
			>
				{state === "dark"
					? (darkIcon ?? <MoonIcon data-slot="dark-icon" />)
					: (lightIcon ?? <SunIcon data-slot="light-icon" />)}
			</IconSwapItem>
		</IconSwap>
	);
}

export type ThemeToggleProps = ComponentProps<typeof Button> & {
	/** Called with the resolved theme after it changes. */
	onThemeChange?: (theme: ThemeState) => void;
} & Omit<ThemeStateIconProps, "state">;

export function ThemeToggle({
	className,
	size = "icon",
	children,
	lightIcon,
	darkIcon,
	onClick,
	onThemeChange,
	...props
}: ThemeToggleProps) {
	const { state, toggle } = useThemeToggle({ onThemeChange });
	const label = state
		? `Switch to ${state === "dark" ? "light" : "dark"} theme`
		: "Toggle theme";

	return (
		<Button
			className={cn("will-change-transform", className)}
			size={size}
			onClick={(event) => {
				toggle();
				onClick?.(event);
			}}
			aria-label={label}
			data-state={state ?? "loading"}
			{...props}
		>
			<ThemeStateIcon state={state} lightIcon={lightIcon} darkIcon={darkIcon} />
			{children}
		</Button>
	);
}

export default ThemeToggle;

"use client";

import type { AnimatePresenceProps, HTMLMotionProps } from "motion/react";
import { AnimatePresence, motion } from "motion/react";

export function IconSwap(props: React.PropsWithChildren<AnimatePresenceProps>) {
	return <AnimatePresence mode="popLayout" initial={false} {...props} />;
}

type MotionElement = typeof motion.div | typeof motion.span;

export function IconSwapItem({
	as: Component = motion.div,
	...props
}: HTMLMotionProps<"div"> & {
	as?: MotionElement;
}) {
	return (
		<Component
			initial={{ opacity: 0, scale: 0.25, filter: "blur(4px)" }}
			animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
			exit={{ opacity: 0, scale: 0.25, filter: "blur(4px)" }}
			transition={{
				type: "spring",
				duration: 0.3,
				bounce: 0,
			}}
			{...props}
		/>
	);
}

"use client";

import { useTheme } from "next-themes";
import { useCallback, useEffect, useState } from "react";
import { useWebHaptics } from "web-haptics/react";
import { useMetalClickSound } from "@/hooks/soundcn/use-metal-click-sound";

export type ThemeState = "light" | "dark";

export type UseThemeToggleOptions = {
	onThemeChange?: (theme: ThemeState) => void;
};

export function useThemeToggle({ onThemeChange }: UseThemeToggleOptions = {}) {
	const { resolvedTheme, systemTheme, setTheme } = useTheme();
	const { trigger: haptic } = useWebHaptics();
	const [playClick] = useMetalClickSound();
	const [mounted, setMounted] = useState(false);

	useEffect(() => setMounted(true), []);

	const state: ThemeState | null =
		mounted && (resolvedTheme === "light" || resolvedTheme === "dark")
			? resolvedTheme
			: null;

	const toggle = useCallback(() => {
		const nextTheme: ThemeState = state === "dark" ? "light" : "dark";

		setTheme(nextTheme === systemTheme ? "system" : nextTheme);
		playClick();
		void haptic("selection");
		onThemeChange?.(nextTheme);
	}, [state, systemTheme, setTheme, playClick, haptic, onThemeChange]);

	return { state, toggle } as const;
}

import { metalClickSound } from "@/lib/soundcn/metal-click";

import { useSound } from "./use-sound";

export function useMetalClickSound() {
	return useSound(metalClickSound, { volume: 0.1 });
}

"use client";

import { useReducedMotion } from "motion/react";
import { useCallback, useEffect, useRef, useState } from "react";

import { decodeAudioData, getAudioContext } from "@/lib/soundcn/sound-engine";
import type {
	SoundAsset,
	UseSoundOptions,
	UseSoundReturn,
} from "@/lib/soundcn/sound-types";

export function useSound(
	sound: SoundAsset,
	options: UseSoundOptions = {},
): UseSoundReturn {
	const {
		volume = 0.5,
		playbackRate = 1,
		interrupt = false,
		soundEnabled: _soundEnabled = true,
		onPlay,
		onEnd,
		onPause,
		onStop,
	} = options;

	const [isPlaying, setIsPlaying] = useState(false);
	const [duration, setDuration] = useState<number | null>(
		sound.duration ?? null,
	);
	const sourceRef = useRef<AudioBufferSourceNode | null>(null);
	const gainRef = useRef<GainNode | null>(null);
	const bufferRef = useRef<AudioBuffer | null>(null);

	const shouldReduceMotion = useReducedMotion();
	const soundEnabled = _soundEnabled && !shouldReduceMotion;

	useEffect(() => {
		let cancelled = false;

		void decodeAudioData(sound.dataUri)
			.then((buffer) => {
				if (!cancelled) {
					bufferRef.current = buffer;
					setDuration(buffer.duration);
				}
			})
			.catch(() => {
				if (!cancelled) {
					bufferRef.current = null;
					setDuration(sound.duration ?? null);
				}
			});

		return () => {
			cancelled = true;
		};
	}, [sound.dataUri, sound.duration]);

	const stop = useCallback(() => {
		if (sourceRef.current) {
			try {
				sourceRef.current.stop();
			} catch {
				// Already stopped
			}
			sourceRef.current = null;
		}
		setIsPlaying(false);
		onStop?.();
	}, [onStop]);

	const play = useCallback(
		(overrides?: { volume?: number; playbackRate?: number }) => {
			if (!soundEnabled || !bufferRef.current) return;

			const ctx = getAudioContext();

			if (ctx.state === "suspended") {
				ctx.resume();
			}

			if (interrupt && sourceRef.current) {
				stop();
			}

			const source = ctx.createBufferSource();
			const gain = ctx.createGain();

			source.buffer = bufferRef.current;
			source.playbackRate.value = overrides?.playbackRate ?? playbackRate;
			gain.gain.value = overrides?.volume ?? volume;

			source.connect(gain);
			gain.connect(ctx.destination);

			source.onended = () => {
				setIsPlaying(false);
				onEnd?.();
			};

			source.start(0);
			sourceRef.current = source;
			gainRef.current = gain;
			setIsPlaying(true);
			onPlay?.();
		},
		[soundEnabled, playbackRate, volume, interrupt, stop, onPlay, onEnd],
	);

	const pause = useCallback(() => {
		stop();
		onPause?.();
	}, [stop, onPause]);

	useEffect(() => {
		if (gainRef.current) {
			gainRef.current.gain.value = volume;
		}
	}, [volume]);

	useEffect(() => {
		return () => {
			if (sourceRef.current) {
				try {
					sourceRef.current.stop();
				} catch {
					// Already stopped
				}
			}
		};
	}, []);

	return [play, { stop, pause, isPlaying, duration, sound }] as const;
}

import type { SoundAsset } from "@/lib/soundcn/sound-types";

export const metalClickSound: SoundAsset = {
	name: "metal-click",
	dataUri:
		"data:audio/mpeg;base64,",
	duration: 0.446,
	format: "mp3",
	license: "CC0",
	author: "Kenney",
};

let audioContext: AudioContext | null = null;
const bufferCache = new Map<string, AudioBuffer>();

export function getAudioContext(): AudioContext {
	if (!audioContext) {
		audioContext = new AudioContext();
	}
	return audioContext;
}

export async function decodeAudioData(dataUri: string): Promise<AudioBuffer> {
	const cached = bufferCache.get(dataUri);
	if (cached) return cached;

	const context = getAudioContext();
	const base64 = dataUri.split(",")[1];
	if (!base64) throw new Error("Invalid sound data URI");

	const binaryString = atob(base64);
	const bytes = new Uint8Array(binaryString.length);
	for (let index = 0; index < binaryString.length; index++) {
		bytes[index] = binaryString.charCodeAt(index);
	}

	const audioBuffer = await context.decodeAudioData(bytes.buffer.slice(0));
	bufferCache.set(dataUri, audioBuffer);
	return audioBuffer;
}

export interface SoundAsset {
	name: string;
	dataUri: string;
	duration: number;
	format: "mp3" | "wav" | "ogg";
	license: "CC0" | "OGA-BY" | "MIT";
	author: string;
}

export interface UseSoundOptions {
	volume?: number;
	playbackRate?: number;
	interrupt?: boolean;
	soundEnabled?: boolean;
	onPlay?: () => void;
	onEnd?: () => void;
	onPause?: () => void;
	onStop?: () => void;
}

export type PlayFunction = (overrides?: {
	volume?: number;
	playbackRate?: number;
}) => void;

export interface SoundControls {
	stop: () => void;
	pause: () => void;
	isPlaying: boolean;
	duration: number | null;
	sound: SoundAsset;
}

export type UseSoundReturn = readonly [PlayFunction, SoundControls];
